
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_sogga11_x_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_sogga11_x", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.121905580739231e-01, -1.121005323841921e-01, -1.119146216706299e-01, -1.115322130427294e-01, -1.107661690849868e-01, -1.093636212897008e-01, -1.075269921783420e-01, -1.088954855096886e-01, -1.290643166248707e-01, -1.813081843759876e-01, -1.538779488151377e-01, -4.955533094194940e-02, -4.878458208881697e-02, -4.311563030720882e-02, -4.256599338352623e-02, -4.749481705830562e-02, -7.834692428071886e-02, -3.184999050022175e-02, -8.317708382196755e-03, -1.178153639822412e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


